// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GeneralSettings) predicate.GeneralSettings {
	return predicate.GeneralSettings(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GeneralSettings) predicate.GeneralSettings {
	return predicate.GeneralSettings(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GeneralSettings) predicate.GeneralSettings {
	return predicate.GeneralSettings(sql.NotPredicates(p))
}
